#include <stdlib.h>

typedef struct { int u, v, w; } E;

static int cmp(const void *a, const void *b) {
  return ((const E *)a)->w - ((const E *)b)->w;   /* assumes no overflow */
}

static int find(int p[], int x) {
  while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; }
  return x;
}

/* returns total weight; picked[] receives the chosen edges, count in *k */
long kruskal(int V, E edges[], int m, E picked[], int *k) {
  int p[V], sz[V]; long total = 0; *k = 0;
  for (int i = 0; i < V; i++) { p[i] = i; sz[i] = 1; }
  qsort(edges, m, sizeof(E), cmp);
  for (int i = 0; i < m && *k < V - 1; i++) {
    int a = find(p, edges[i].u), b = find(p, edges[i].v);
    if (a == b) continue;                 /* would close a cycle */
    if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
    p[b] = a; sz[a] += sz[b];
    picked[(*k)++] = edges[i];
    total += edges[i].w;
  }
  return total;                           /* *k < V - 1 means disconnected */
}

#include <limits.h>

/* g[u][v] == 0 means no edge; returns total MST weight, parent[] holds the tree */
long prim(int V, int g[V][V], int parent[]) {
  int key[V], in[V]; long total = 0;
  for (int i = 0; i < V; i++) { key[i] = INT_MAX; in[i] = 0; parent[i] = -1; }
  key[0] = 0;
  for (int round = 0; round < V; round++) {
    int u = -1;
    for (int v = 0; v < V; v++)
      if (!in[v] && (u == -1 || key[v] < key[u])) u = v;
    if (key[u] == INT_MAX) break;         /* graph is disconnected */
    in[u] = 1;
    total += key[u];
    for (int v = 0; v < V; v++)
      if (g[u][v] && !in[v] && g[u][v] < key[v]) {
        key[v] = g[u][v];                 /* cheapest edge into the tree */
        parent[v] = u;
      }
  }
  return total;
}
